import LanguageDisplay from '../components/LanguageDisplay';
import app from 'flarum/forum/app';
export default function generateLanguageOptions(extraOptions) {
  const options = {};
  const languages = app.store.all('discussion-languages');

  // Populate the options with the languages
  languages.forEach(lang => {
    options[lang.code()] = m(LanguageDisplay, {
      language: lang
    });
  });

  // Merge extra options, if provided
  return {
    ...options,
    ...extraOptions
  };
}
flarum.reg.add('fof-discussion-language', 'forum/utils/generateLanguageOptions', generateLanguageOptions);