import { extend, override } from 'flarum/common/extend';
import app from 'flarum/forum/app';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import LanguageDiscussionModal from './components/LanguageDiscussionModal';
import LanguageDisplay from './components/LanguageDisplay';
import composerFields from './utils/composerFields';
import currentLanguage from './utils/currentLanguage';
const sort = (a, b) => a.code().toLowerCase() > b.code().toLowerCase() ? 1 : -1;
export default () => {
  extend(IndexSidebar.prototype, 'newDiscussionAction', function (promise) {
    const dislang = currentLanguage();
    if (dislang) {
      promise.then(() => composerFields().language = app.store.getBy('discussion-languages', 'code', dislang), () => {});
    } else {
      const localeComposer = app.forum.attribute('fof-discussion-language.composerLocaleDefault');
      composerFields().language = localeComposer ? app.store.getBy('discussion-languages', 'code', app.translator.getLocale()) : '';
    }
  });
  extend('flarum/forum/components/DiscussionComposer', 'oninit', function () {
    this.constructor.prototype.chooseLanguage = function (hide, callback) {
      app.modal.show(LanguageDiscussionModal, {
        selected: composerFields().language || undefined,
        hideSubmitButton: hide,
        onsubmit: language => {
          composerFields().language = language;
          this.$('textarea').focus();
          if (callback) callback();
        }
      });
    };
  });
  extend('flarum/forum/components/DiscussionComposer', 'headerItems', function (items) {
    // Don't add lang item to byobu composers
    if (this._isByobuComposer) return;
    const language = composerFields().language;
    items.add('language', m("a", {
      className: "DiscussionComposer-changeTags",
      onclick: this.chooseLanguage.bind(this, true, null)
    }, m("span", {
      className: `LanguageLabel ${language ? '' : 'none'}`
    }, language ? m(LanguageDisplay, {
      language: language,
      uppercase: true
    }) : app.translator.trans('fof-discussion-language.forum.composer_discussion.choose_language_link'))), 20);
  });
  override('flarum/forum/components/DiscussionComposer', 'onsubmit', function (original) {
    // Don't add lang stuff to byobu composers
    if (this._isByobuComposer) return original();
    if (!composerFields().language) return this.chooseLanguage(true, original);
    original();
  });
  extend('flarum/forum/components/DiscussionComposer', 'data', function (data) {
    // Don't add lang stuff to byobu composers
    if (this._isByobuComposer) return;
    data.relationships = data.relationships || {};
    data.relationships.language = composerFields().language || app.store.all('discussion-languages').sort(sort)[0];
  });
};