import app from 'flarum/forum/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import LanguageDisplay from './LanguageDisplay';
export default class LanguageDiscussionModal extends FormModal {
  oninit(vnode) {
    super.oninit(vnode);
    this.languages = app.store.all('discussion-languages').filter(language => language.code() !== 'any');
    this.current = this.attrs.selected || this.attrs.discussion && this.attrs.discussion.language?.() || undefined;
    this.selected = this.current;
  }
  className() {
    return 'FoFLanguageDiscussionModal';
  }
  title() {
    return this.attrs.discussion ? app.translator.trans('fof-discussion-language.forum.change_language.edit_title', {
      title: m("em", null, this.attrs.discussion.title())
    }) : app.translator.trans('fof-discussion-language.forum.change_language.title');
  }
  content() {
    return [m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form-group"
    }, this.languages.map(language => m(Button, {
      onclick: this.select.bind(this, language),
      className: `Button Button--block ${this.selected === language ? 'active' : ''}`
    }, m(LanguageDisplay, {
      language: language,
      uppercase: true
    })))), !this.attrs.hideSubmitButton && m("div", {
      className: "App-primaryControl"
    }, Button.component({
      type: 'submit',
      className: 'Button Button--primary',
      disabled: !this.selected || this.selected === this.current,
      loading: this.loading,
      icon: 'fas fa-check'
    }, app.translator.trans('fof-discussion-language.forum.change_language.submit_button'))))];
  }
  select(language) {
    this.selected = language;
    if (this.attrs.hideSubmitButton) return this.onsubmit();
    m.redraw();
  }
  onsubmit(e) {
    if (e) e.preventDefault();
    const {
      discussion,
      onsubmit
    } = this.attrs;
    this.loading = true;
    if (!discussion) {
      this.hide();
      if (onsubmit && this.selected) onsubmit(this.selected);
      return;
    }
    const language = this.selected ?? null;
    discussion.save({
      relationships: {
        language
      }
    }).then(() => this.hide()).catch(this.loaded.bind(this));
  }
}
flarum.reg.add('fof-discussion-language', 'forum/components/LanguageDiscussionModal', LanguageDiscussionModal);